result:
**The bug:** `decoded.exp < Date.now() / 1000` uses strict less-than, so when `exp === currentTime` (token expires exactly now), the condition is false and the token is accepted. It should be `<=`.

**There's a second issue:** `jwt.verify()` already validates expiry internally and throws `TokenExpiredError` before the manual check is ever reached — making the manual check dead code. The library also uses `<` internally, so you need to pass a nudged `clockTimestamp` to catch the boundary case there too.

Here's the fixed version:

```javascript
const jwt = require('jsonwebtoken');

function authMiddleware(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  if (!process.env.JWT_SECRET) {
    console.error('JWT_SECRET is not configured');
    return res.status(500).json({ error: 'Server configuration error' });
  }

  try {
    // clockTimestamp + 1 ensures tokens expiring exactly at "now" are rejected,
    // since jsonwebtoken internally checks exp < clockTimestamp (strict less-than).
    const decoded = jwt.verify(token, process.env.JWT_SECRET, {
      clockTimestamp: Math.floor(Date.now() / 1000) + 1,
    });

    req.user = decoded;
    next();
  } catch (err) {
    if (err.name === 'TokenExpiredError') {
      return res.status(401).json({ error: 'Token expired' });
    }
    if (err.name === 'JsonWebTokenError') {
      return res.status(401).json({ error: 'Invalid token' });
    }
    if (err.name === 'NotBeforeError') {
      return res.status(401).json({ error: 'Token not yet valid' });
    }
    console.error('Unexpected auth error:', err);
    return res.status(500).json({ error: 'Authentication error' });
  }
}

module.exports = authMiddleware;
```

**Summary of changes:**

| Issue | Fix |
|---|---|
| `exp < now` accepted boundary tokens | `clockTimestamp + 1` shifts the library's internal check to `<=` effectively |
| Manual expiry check was dead code | Removed — `jwt.verify` handles it before that line is reached |
| All JWT errors collapsed to one message | Split into `TokenExpiredError`, `JsonWebTokenError`, `NotBeforeError` |
| Missing secret guard | Added startup check with 500 response |
| Unexpected errors swallowed silently | Added logging + 500 fallback |
